#!/usr/bin/env bash
# Sprocket's plain-Java parts on the desktop JDK (org.json from android/test: android.jar's is a stub).
set -euo pipefail
cd "$(dirname "$0")/.."
A=$HOME/.local/android; J=$A/jdk/bin; [ -d "$J" ] || J=$(dirname "$(command -v javac)")
PLAT=${ANDROID_HOME:-$A/sdk}/platforms/android-35/android.jar
T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
S=android/src/dev/sprocket/app
# adb wireless pairing (ported from Mika): every file except the two Android-only ones (NSD discovery, Keystore/exporter glue).
ADB=$(ls $S/adb/*.java | grep -v -e /AndroidAdb.java -e /NsdAdbServiceFinder.java)
"$J/javac" -encoding UTF-8 -cp "$PLAT" -d "$T" android/test/org/json/*.java $S/Claude.java $S/UndoLog.java $S/OpenAiWire.java $S/Chat.java $S/Speech.java $S/Weather.java $S/PhoneTools.java $S/NameMatch.java $S/Memory.java $S/VoiceGroups.java $S/Research.java $S/Markdown.java $S/Lists.java $S/Messages.java $S/Notices.java $S/Machines.java $S/GitHub.java $S/Goals.java $S/Feed.java $S/Studio.java $S/Conversation.java $S/Screen.java $S/Calls.java $S/NotionSync.java $S/Config.java $S/Speechy.java $S/Listen.java $S/Setup.java $ADB $S/AppNotes.java $S/Tv.java $S/Lg.java $S/Schedules.java $S/Reminders.java android/src/dev/sprocket/bg/BgHelper.java \
  android/test/ClaudeTest.java android/test/OpenAiWireTest.java android/test/ChatTest.java android/test/SpeechTest.java android/test/WeatherTest.java android/test/PhoneToolsTest.java android/test/NameMatchTest.java android/test/MemoryTest.java android/test/VoiceGroupsTest.java android/test/ResearchTest.java android/test/ListsTest.java android/test/MessagesTest.java android/test/NoticesTest.java android/test/MachinesTest.java android/test/GitHubTest.java android/test/GoalsTest.java android/test/FeedTest.java android/test/StudioTest.java android/test/ConversationTest.java android/test/DoorTest.java android/test/ScreenTest.java android/test/CallsTest.java android/test/NotionSyncTest.java android/test/ConfigTest.java android/test/SpeechyTest.java android/test/SetupTest.java android/test/CheckTest.java android/test/AdbTest.java android/test/AppNotesTest.java android/test/UndoLogTest.java android/test/TvTest.java android/test/SchedulesTest.java android/test/RemindersTest.java android/test/BgHelperTest.java
for t in ClaudeTest OpenAiWireTest ChatTest SpeechTest WeatherTest PhoneToolsTest NameMatchTest MemoryTest VoiceGroupsTest ResearchTest ListsTest MessagesTest NoticesTest MachinesTest GitHubTest GoalsTest FeedTest StudioTest ConversationTest DoorTest ScreenTest CallsTest NotionSyncTest ConfigTest SpeechyTest SetupTest CheckTest AppNotesTest UndoLogTest TvTest SchedulesTest RemindersTest BgHelperTest adb.AdbTest; do "$J/java" -cp "$T:$PLAT" dev.sprocket.app.$t; done   # $T first: the test org.json
